    JSON

    CLAIM_MAP = JSON.parse(CLAIM_MAP_JSON).freeze
    KINDS = CLAIM_MAP['kinds'].transform_values do |kind|
      [Regexp.new("\\A(?:#{kind['pattern']})\\z"), kind['maxLength']]
    end.freeze
    SLUG = Regexp.new("\\A(?:#{CLAIM_MAP['slug']})\\z")
    SPLITTERS = {
      'whitespace' => /[ \t\r\n\f\v]+/,
      'comma_whitespace' => /[ \t\r\n\f\v,]+/
    }.freeze
    MAX_TIME = 253_402_300_799

    class << self
      # Map verified WorkOS AuthKit claims plus verified user or session record overrides.
      def from_workos(claims, overrides = nil)
        build('workos', 'workos', claims, overrides)
      end

      # Map verified Clerk session claims. Pass Session.created_at as :session_created_at.
      def from_clerk(claims, overrides = nil)
        build('clerk', 'clerk', claims, overrides)
      end

      # Map verified Auth0 ID token, userinfo or normalised session claims.
      # Do not pass an opaque API access token.
      def from_auth0(claims, overrides = nil)
        build('auth0', 'auth0', claims, overrides)
      end

      # Map verified Supabase Auth access token claims (legacy HS256 secret or JWKS).
      # Pass the user record's contact verification as overrides.
      def from_supabase(claims, overrides = nil)
        build('supabase', 'supabase', claims, overrides)
      end

      # Map verified Firebase ID token claims from the Admin SDK verifyIdToken.
      # Custom claims never change the mapping.
      def from_firebase(claims, overrides = nil)
        build('firebase', 'firebase', claims, overrides)
      end

      # Map verified Amazon Cognito user pool ID or access token claims.
      # Claims added by a pre token generation Lambda never change the mapping.
      def from_cognito(claims, overrides = nil)
        build('cognito', 'cognito', claims, overrides)
      end

      # Map verified Microsoft Entra ID v1.0 or v2.0 ID or access token claims.
      def from_entra(claims, overrides = nil)
        build('entra', 'entra', claims, overrides)
      end

      # Map verified Keycloak ID or access token claims.
      def from_keycloak(claims, overrides = nil)
        build('keycloak', 'keycloak', claims, overrides)
      end

      # Map an Ory session from toSession (Kratos FrontendApi).
      # Pass your project URL as the :issuer override.
      def from_ory(session, overrides = nil)
        build('ory', 'ory', session, overrides)
      end

      # Map verified Ory OAuth2 and OpenID Connect (Hydra) ID token claims.
      def from_ory_oauth2(claims, overrides = nil)
        build('ory_oauth2', 'ory', claims, overrides)
      end

      # Generic OIDC adapter for providers without a first-class helper.
      # provider is a lowercase slug.
      def from_oidc(provider, claims, overrides = nil)
        raise ArgumentError, 'provider must be a lowercase provider slug' unless provider.is_a?(String) && SLUG.match?(provider)

        build('oidc', provider, claims, overrides)
      end

      private

      def lookup(claims, path)
        current = claims
        path.split('.').each do |key|
          return nil unless current.is_a?(Hash) && current.key?(key)

          current = current[key]
        end
        current
      end

      def number?(value)
        value.is_a?(Integer) || (value.is_a?(Float) && value.finite?)
      end

      def matches?(kind, value)
        pattern, limit = KINDS.fetch(kind)
        value.is_a?(String) && value.length <= limit && pattern.match?(value)
      end

      def lower(value)
        value.tr('A-Z', 'a-z')
      end

      def map_rule(claims, rule)
        case rule['op']
        when 'id'
          rule['claims'].each do |path|
            value = lookup(claims, path)
            value = value[0] if rule['single'] && value.is_a?(Array) && value.length == 1
            return value if matches?(rule['kind'], value)
          end
          nil
        when 'list' then map_list(claims, rule)
        when 'time' then map_time(claims, rule)
        when 'bool'
          rule['claims'].each do |path|
            value = lookup(claims, path)
            return value if [true, false].include?(value)
          end
          nil
        when 'actor'
          acting = rule['claims'].any? do |path|
            value = lookup(claims, path)
            if value.is_a?(Hash)
              %w[sub email].any? { |key| value[key].is_a?(String) && !value[key].empty? }
            else
              value.is_a?(String) && !value.empty?
            end
          end
          acting || (rule['onlyTrue'] ? nil : false)
        when 'mfa_factor_age'
          value = lookup(claims, rule['claim'])
          age = value.is_a?(Array) ? value[rule['index']] : nil
          return nil unless number?(age)

          seconds = age * rule['unitSeconds']
          return nil unless seconds >= 0 && seconds <= rule['maxSeconds']

          { 'present' => true, 'age_seconds' => seconds.to_i }
        when 'mfa_aal'
          level = lookup(claims, rule['claim'])
          return nil unless level.is_a?(String)
          return { 'present' => false } if rule['absent'].include?(level)
          return nil unless rule['present'].include?(level)

          entries = lookup(claims, rule['amr'])
          methods = []
          (entries.is_a?(Array) ? entries : []).each do |entry|
            if rule.key?('levelKey')
              level_value = entry.is_a?(Hash) ? entry[rule['levelKey']] : nil
              next unless level_value.is_a?(String) && rule['present'].include?(level_value)
            end
            name = entry.is_a?(Hash) ? entry[rule['methodKey']] : entry
            mapped = name.is_a?(String) ? rule['factors'][name] : nil
            methods << mapped if mapped && !methods.include?(mapped)
          end
          methods.empty? ? { 'present' => true } : { 'present' => true, 'methods' => methods }
        when 'mfa_factor'
          value = lookup(claims, rule['claim'])
          matches?(rule['kind'], value) ? { 'present' => true, 'methods' => [value] } : nil
        when 'marker'
          hit = rule['when'].any? do |test|
            value = lookup(claims, test['claim'])
            value.instance_of?(test['equals'].class) && value == test['equals']
          end
          hit ? rule['value'] : nil
        when 'mfa_methods'
          value = lookup(claims, rule['claim'])
          return nil unless value.is_a?(Array)

          kept = value.select { |item| matches?(rule['kind'], item) }.first(rule['max'])
          methods = kept.reject { |item| rule['ignore'].include?(lower(item)) }
          return nil if methods.empty?

          classes = rule['classes'] || {}
          spanned = kept.map { |item| classes[lower(item)] }.compact.uniq
          present = kept.any? { |item| lower(item) == rule['mfaValue'] } || spanned.length >= 2
          { 'present' => present, 'methods' => methods }
        else
          raise ArgumentError, "unknown claim map op #{rule['op']}"
        end
      end

      def map_list(claims, rule)
        split = rule['split'] || 'whitespace'
        rule['claims'].each do |path|
          value = lookup(claims, path)
          items = list_items(value, split)
          kept = items.select { |item| matches?(rule['kind'], item) }.first(rule['max'])
          return kept unless kept.empty?
        end
        nil
      end

      def list_items(value, split)
        return value if value.is_a?(Array)
        return [] unless value.is_a?(String)

        split == 'none' ? [value] : value.split(SPLITTERS.fetch(split))
      end

      def map_time(claims, rule)
        rule['claims'].each do |path|
          value = lookup(claims, path)
          # Whole UTC seconds; the fraction is truncated.
          return Time.at(value.to_i).utc.strftime('%Y-%m-%dT%H:%M:%SZ') if number?(value) && value >= 0 && value <= MAX_TIME
          return value if matches?('time', value)
        end
        nil
      end

      def normalise(value)
        JSON.parse(JSON.generate(value.nil? ? {} : value))
      end

      def build(name, provider, raw_claims, raw_overrides)
        claims = normalise(raw_claims)
        overrides = normalise(raw_overrides)
        spec = CLAIM_MAP['providers'].fetch(name)
        rules = CLAIM_MAP['base'].merge(spec['fields'])
        (spec['disable'] || []).each { |field| rules.delete(field) }
        wire = { 'provider' => provider }.merge(CLAIM_MAP['constants'])
        rules.each do |field, rule|
          value = map_rule(claims, rule)
          wire[field] = value unless value.nil?
        end
        overrides.each { |field, value| wire[field] = value unless value.nil? }
        audiences = wire['audiences']
        wire['audience'] = audiences[0] if audiences.is_a?(Array) && !audiences.empty? && !wire.key?('audience')
        %w[issuer subject].each do |key|
          unless wire[key].is_a?(String) && !wire[key].empty?
            raise ArgumentError, 'NoResponse auth context requires a verified issuer and subject'
          end
        end
        Models::Shared::AuthContext.from_dict(wire)
      end
    end
  end
end
